<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Recruiter Clients</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Manage Client Companies</h2><?php if (!empty($error)): ?><div class="alert alert-error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><form method="post" action="index.php?route=recruiter/clients"><label>Standalone Company Name</label><input name="company_name_override" required placeholder="e.g. Acme Ltd"><div class="actions"><button type="submit">Add Client</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></form><h3>Your Clients</h3><div class="table-wrap"><table><tr><th>ID</th><th>Company</th><th>Employer Linked</th><th>Added At</th></tr><?php foreach ($clients as $client): ?><tr><td><?php echo (int)$client['id']; ?></td><td><?php echo htmlspecialchars($client['company_name_override'] ?? $client['employer_company_name'] ?? 'N/A'); ?></td><td><?php echo $client['employer_id'] ? 'Yes' : 'No'; ?></td><td><?php echo htmlspecialchars($client['added_at']); ?></td></tr><?php endforeach; ?></table></div></div></body></html>
